class AmountSorter {

    private static final Logger log = Logger.getLogger(AmountSorter.class.getName());

    void sort(int[] a) {
        quickSort(a, 0, a.length - 1);
    }

    private void quickSort(int[] a, int lo, int hi) {
        if (lo >= hi) return;                    // 0 or 1 element → sorted
        int p = partition(a, lo, hi);            // pivot now in final place
        quickSort(a, lo, p - 1);                 // sort left part
        quickSort(a, p + 1, hi);                 // sort right part
    }

    // Lomuto partition with median-of-three pivot moved to the end.
    private int partition(int[] a, int lo, int hi) {
        int mid = lo + (hi - lo) / 2;
        int pivotIndex = medianOfThree(a, lo, mid, hi);
        swap(a, pivotIndex, hi);                 // park pivot at the end
        int pivot = a[hi];

        int boundary = lo;                       // end of the "smaller" region
        for (int i = lo; i < hi; i++) {
            if (a[i] < pivot) {
                swap(a, i, boundary);
                boundary++;
            }
        }
        swap(a, boundary, hi);                   // place pivot in its final slot
        final int settled = boundary;            // capture for the lambda
        log.fine(() -> "  pivot " + pivot + " settled at index " + settled);
        return boundary;
    }

    private int medianOfThree(int[] a, int i, int j, int k) {
        if (a[i] < a[j]) {
            if (a[j] < a[k]) return j;
            return a[i] < a[k] ? k : i;
        } else {
            if (a[i] < a[k]) return i;
            return a[j] < a[k] ? k : j;
        }
    }

    private void swap(int[] a, int i, int j) {
        int tmp = a[i]; a[i] = a[j]; a[j] = tmp;
    }
}

